// ── Feature pipeline and model registry in code ─────────────────

// 1. Feature validation — fail loudly before bad data contaminates models
function validateRecord(record) {
  const errors = [];

  if (typeof record.age !== 'number' || record.age < 0 || record.age > 150)
    errors.push(`Invalid age: ${record.age}`);

  if (typeof record.purchaseAmount !== 'number' || record.purchaseAmount < 0)
    errors.push(`Invalid purchaseAmount: ${record.purchaseAmount}`);

  if (!['web', 'mobile', 'api'].includes(record.channel))
    errors.push(`Unknown channel: ${record.channel}`);

  if (errors.length > 0)
    throw new Error(`Validation failed: ${errors.join('; ')}`);

  return true;
}

// 2. Feature computation — SAME function used in training batch AND serving
// This is the core principle that a feature store enforces.
function computeFeatures(rawRecord) {
  return {
    ageNormalised:   (rawRecord.age - 30) / 20,          // z-score approx (mean=30, std=20)
    logAmount:       Math.log1p(rawRecord.purchaseAmount), // log(1+x) handles 0 gracefully
    isWebChannel:    rawRecord.channel === 'web'    ? 1 : 0,
    isMobileChannel: rawRecord.channel === 'mobile' ? 1 : 0,
    hourOfDay:       new Date(rawRecord.timestamp).getUTCHours()
    // Note: always UTC — timezone bugs are a common source of skew
  };
}

// 3. Model registry — version control for trained models
// In production: MLflow Model Registry, W&B, SageMaker Model Registry
const modelRegistry = new Map();

function registerModel(name, version, metrics, artifact) {
  if (!name || !version || !metrics || !artifact)
    throw new Error('Missing required fields for model registration');

  const key = `${name}@${version}`;
  modelRegistry.set(key, {
    name,
    version,
    metrics,
    artifact,
    stage: 'staging',           // staging → production → archived
    registeredAt: new Date().toISOString(),
    approved: false
  });
  console.log(`[Registry] Registered ${key} | AUC: ${metrics.auc}`);
  return key;
}

function promoteToProduction(name, version) {
  // First, archive any existing production model
  for (const [key, entry] of modelRegistry.entries()) {
    if (entry.name === name && entry.stage === 'production') {
      entry.stage = 'archived';
      console.log(`[Registry] Archived ${key}`);
    }
  }
  const key = `${name}@${version}`;
  const entry = modelRegistry.get(key);
  if (!entry) throw new Error(`Model ${key} not found in registry`);
  entry.stage = 'production';
  entry.approved = true;
  console.log(`[Registry] Promoted ${key} to PRODUCTION`);
  return key;
}

function getProductionModel(name) {
  for (const entry of modelRegistry.values()) {
    if (entry.name === name && entry.stage === 'production') return entry;
  }
  return null;
}

// Demo: training run 1 → register → promote
registerModel('fraud-detector', 'v1.2', { accuracy: 0.94, auc: 0.97 }, '/models/fraud/v1.2');
promoteToProduction('fraud-detector', 'v1.2');

// New training run with better metrics
registerModel('fraud-detector', 'v1.3', { accuracy: 0.955, auc: 0.982 }, '/models/fraud/v1.3');
// Only promote after A/B test confirms improvement:
promoteToProduction('fraud-detector', 'v1.3');
// v1.2 is now archived (safe rollback point)

console.log('Production model:', getProductionModel('fraud-detector').version); // v1.3

// 4. Serving — feature pipeline is identical to training computation
const rawRequest = {
  age: 35, purchaseAmount: 149.99, channel: 'web', timestamp: Date.now()
};
validateRecord(rawRequest);
const features = computeFeatures(rawRequest);
console.log('Serving features:', features);
// These features are IDENTICAL to what training used — no skew possible

// ── Drift detection: Population Stability Index (PSI) ────────────
//
// PSI measures how much a feature's distribution has shifted
// between training (expected) and production (actual).
// Thresholds: < 0.1 stable | 0.1-0.25 moderate | > 0.25 significant drift

function computePSI(expected, actual, bins = 10) {
  if (expected.length === 0 || actual.length === 0)
    throw new Error('PSI requires non-empty arrays');

  // Determine bin boundaries from both distributions combined
  const all = [...expected, ...actual].sort((a, b) => a - b);
  const min = all[0];
  const max = all[all.length - 1];
  const binWidth = (max - min) / bins || 1; // guard against zero-width

  function toProportion(arr) {
    const counts = new Array(bins).fill(0);
    for (const v of arr) {
      const idx = Math.min(Math.floor((v - min) / binWidth), bins - 1);
      counts[idx]++;
    }
    // Return proportions, floor at 1e-9 to avoid log(0)
    return counts.map(c => Math.max(c / arr.length, 1e-9));
  }

  const expProp = toProportion(expected);
  const actProp = toProportion(actual);

  const psi = expProp.reduce((sum, e, i) => {
    const a = actProp[i];
    return sum + (a - e) * Math.log(a / e); // PSI formula
  }, 0);

  return psi;
}

function interpretPSI(psi) {
  if (psi < 0.1)  return { level: 'stable',   action: 'No action needed' };
  if (psi < 0.25) return { level: 'moderate',  action: 'Investigate root cause' };
  return           { level: 'significant', action: 'TRIGGER RETRAINING — alert on-call' };
}

// Scenario: fraud model feature 'age' — training vs. recent production window
const trainingAges = Array.from({ length: 1000 }, () => 25 + Math.random() * 20);
// 6 months later: a new younger user cohort — significant shift
const productionAges = Array.from({ length: 1000 }, () => 18 + Math.random() * 15);

const psi = computePSI(trainingAges, productionAges);
const result = interpretPSI(psi);
console.log(`PSI = ${psi.toFixed(3)} | ${result.level} | ${result.action}`);
// Likely output: PSI = 0.38x | significant | TRIGGER RETRAINING

// Also monitor: output prediction distribution
function monitorOutputDrift(trainingOutputDist, currentOutputDist) {
  // If mean prediction shifts more than 2 standard deviations, alert
  const trainingMean = trainingOutputDist.reduce((s, v) => s + v, 0) / trainingOutputDist.length;
  const currentMean  = currentOutputDist.reduce((s,  v) => s + v, 0) / currentOutputDist.length;
  const trainingStd  = Math.sqrt(
    trainingOutputDist.reduce((s, v) => s + (v - trainingMean) ** 2, 0) / trainingOutputDist.length
  );
  const zScore = Math.abs(currentMean - trainingMean) / (trainingStd || 1);
  console.log(`Output distribution z-score: ${zScore.toFixed(2)} ${zScore > 2 ? '⚠ ALERT' : '✓ OK'}`);
  return zScore;
}

// Training: fraud rate ~0.5% (model outputs near 0)
const trainingPredictions = Array.from({ length: 10000 }, () =>
  Math.random() < 0.005 ? 0.7 + Math.random() * 0.3 : Math.random() * 0.1
);
// Production spike: fraud campaign — outputs shift higher
const productionPredictions = Array.from({ length: 1000 }, () =>
  Math.random() < 0.08 ? 0.6 + Math.random() * 0.4 : Math.random() * 0.2
);

monitorOutputDrift(trainingPredictions, productionPredictions);
// Will detect significant shift in output mean — alert fires
